// Carte de validation Telegram. HTML échappé (et non Markdown) : un « _ » dans un lien UTM
// ou un « * » dans un texte faisait rejeter tout le message par Telegram.
// sendMessage + aperçu du visuel plutôt que sendPhoto : une légende de photo est limitée à 1 024
// caractères et coupait le texte (et ses liens) avant la validation.
// Carrousel (29/10/2026, plusieurs visuels) : l'album complet part d'abord (sendMediaGroup, par 10),
// puis cette même carte EN RÉPONSE à l'album (reply_parameters, posé par le nœud d'envoi). Le
// message_id stocké reste celui de la CARTE. Un post à une image : carte strictement inchangée.
const cfg = {};
for (const r of $('Aplatir — Lire Config').all()) { if (r.json.Cle) cfg[r.json.Cle] = r.json.Valeur; }
const token = cfg.TELEGRAM_BOT_TOKEN, chatId = cfg.TELEGRAM_CHAT_ID;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const RESEAU = { fb: 'Facebook', ig: 'Instagram', linkedin: 'LinkedIn', x: 'X', tiktok: 'TikTok', youtube: 'YouTube' };
const quand = (v) => { const d = new Date(String(v || '').replace(' ', 'T')); return isNaN(d) ? '?' : d.toLocaleString('fr-FR', { timeZone: 'Africa/Dakar', weekday: 'short', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }); };
const out = [];
for (const it of $('Aplatir — Lire à valider').all()) {
  const p = it.json;
  let media = []; try { media = JSON.parse(p.Visuels_URLs || '[]'); } catch (e) {}
  const photo = media[0];
  const tete = [
    '🆕 <b>Post à valider</b> — ' + esc(RESEAU[p.Reseau] || p.Reseau || '?') + ' · ' + esc(p.Format_Post || ''),
    '🗓 ' + esc(quand(p.Date_Publication_Prevue)) + ' (Dakar)',
    '🏷 ' + esc([p.Serie, p.Offre, p.Cible].filter(Boolean).join(' · ') || '-'),
    '', '<b>' + esc(p.Titre || '') + '</b>', '',
  ].join('\n');
  // Hashtags affichés comme ils seront publiés (WF-SOCIAL-05 les ajoute après le texte).
  const tags = String(p.Hashtags || '').trim();
  const pied = (tags ? '\n\n' + esc(tags) : '\n\n⚠️ aucun hashtag') + (media.length > 1 ? '\n\n🖼 ' + media.length + ' visuels (carrousel)' : '') + '\n\n<i>Id ' + esc(p.id) + '</i>';
  const max = 4096 - tete.length - pied.length - 2;
  let texte = String(p.Texte || '');
  if (esc(texte).length > max) { while (esc(texte).length > max - 1) texte = texte.slice(0, -20); texte += '…'; }
  const cap = tete + esc(texte) + pied;
  const reply_markup = { inline_keyboard: [[
    { text: '✅ Approuver', callback_data: 'approve:post:' + p.id },
    { text: '❌ Rejeter', callback_data: 'reject:post:' + p.id },
  ]] };
  // Un seul message texte (4 096 caractères, texte complet) ; le premier visuel s'affiche
  // en grand au-dessus grâce à l'aperçu de lien.
  const apercu = photo ? { url: photo, prefer_large_media: true, show_above_text: true } : { is_disabled: true };
  const body = { chat_id: chatId, text: cap, parse_mode: 'HTML', reply_markup, link_preview_options: apercu };
  // Carrousel : album d'abord ; la carte, qui répond à l'album, n'a plus besoin de l'aperçu
  // (repris par le nœud d'envoi si l'album échoue : Max voit au moins le 1er visuel).
  const albums = [];
  if (media.length > 1) {
    const n = media.length;
    for (let k = 0; k < n; k += 10) {
      albums.push({ chat_id: chatId, media: media.slice(k, k + 10).map((u, j) => ({
        type: 'photo', media: u, caption: 'Carrousel — Id ' + p.id + ' · ' + (k + j + 1) + '/' + n })) });
    }
    body.link_preview_options = { is_disabled: true };
  }
  const item = { recordId: p.id, token, method: 'sendMessage', body };
  if (albums.length) { item.albums = albums; item.apercuSecours = apercu; }
  out.push({ json: item });
}
return out;

// Envoi Telegram (remplace le nœud HTTP du 29/10/2026). UNE sortie par item du Build, dans le
// même ordre : « Pair notif » apparie par index. Sortie = réponse brute de sendMessage
// ({ ok, result: { message_id } }) ou { error } — comme l'ancien nœud HTTP en continueOnFail.
// Carrousel : sendMediaGroup (album complet) puis la carte en réponse au 1er message de l'album.
const http = this.helpers.httpRequest.bind(this);
const pause = (ms) => (typeof setTimeout === 'function' ? new Promise((r) => setTimeout(r, ms)) : Promise.resolve());
const msgErr = (e) => String((e && e.response && e.response.body && e.response.body.description) || (e && e.description) || (e && e.message) || e).slice(0, 300);
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const api = (method, body) => http({ method: 'POST', url: 'https://api.telegram.org/bot' + j.token + '/' + method, body, json: true });
  const body = Object.assign({}, j.body || {});
  let albumId = null, albumErr = '';
  if (Array.isArray(j.albums) && j.albums.length) {
    for (const lot of j.albums) {
      try {
        // sendMediaGroup exige 2 à 10 médias : un reste isolé (11e visuel…) part en sendPhoto.
        const seul = lot.media.length === 1;
        const r = seul
          ? await api('sendPhoto', { chat_id: lot.chat_id, photo: lot.media[0].media, caption: lot.media[0].caption })
          : await api('sendMediaGroup', lot);
        const m = r && r.ok && (Array.isArray(r.result) ? r.result[0] : r.result);
        if (m && !albumId) albumId = m.message_id;
        if (!m) albumErr = 'sendMediaGroup sans résultat';
      } catch (e) { albumErr = msgErr(e); }
    }
    if (albumId) body.reply_parameters = { message_id: albumId, allow_sending_without_reply: true };
    else if (j.apercuSecours) body.link_preview_options = j.apercuSecours;
    if (albumErr) console.log('album Id ' + j.recordId + ' : ' + albumErr);
    await pause(1000); // un album compte pour N messages côté Telegram : on souffle avant la carte suivante
  }
  try {
    const r = await api(j.method || 'sendMessage', body);
    out.push({ json: Object.assign({}, r, albumId ? { album_message_id: albumId } : {}, albumErr ? { album_erreur: albumErr } : {}) });
  } catch (e) {
    out.push({ json: { error: msgErr(e), album_erreur: albumErr || undefined } });
  }
}
return out;

